const input = ($json.body.chatInput || $json.body.message || '').toLowerCase();
let reply = '';

if (input.includes('timing') || input.includes('hour') || input.includes('open')) {
  reply = '🕒 **UrbanNest Store Hours:** Mon–Sat 10:00 AM – 8:30 PM, Sun 11:00 AM – 7:00 PM. Our web store is open 24/7!';
} else if (input.includes('locate') || input.includes('address') || input.includes('where')) {
  reply = '📍 **Store Location:** 142 Heritage Boulevard, Artisan Quarter, Design District (Opposite Central Botanical Garden Gate #2).';
} else if (input.includes('product') || input.includes('sell') || input.includes('category')) {
  reply = '✨ **Our Collections:** Handcrafted Home Décor, Bespoke Gift Items, Artisan Stationery, Lifestyle Accessories, and Small Household Goods.';
} else if (input.includes('deliver') || input.includes('ship')) {
  reply = '🚚 **Delivery:** Same-day local express delivery is available! Free shipping across the city on orders over $35.';
} else if (input.includes('contact') || input.includes('call') || input.includes('phone')) {
  reply = '📞 **Reach Us:** Phone +1 (555) 382-6637 or WhatsApp us anytime using the button on screen!';
} else if (input.includes('query') || input.includes('form')) {
  reply = '📋 **Submit Query:** You can submit custom gift box or bulk order queries directly using our on-page Query Form!';
} else {
  reply = '🌿 Thank you for reaching out to UrbanNest AI Assistant! We are delighted to assist you with home styling, store timings, and custom gifts.';
}

return [{ json: { output: reply, timestamp: new Date().toISOString() } }];
